trait Speak {
    fn speak(&self) -> String;
}
trait Loud {
    fn loud(&self) -> String;
}
impl<T: Speak> Loud for T {
    fn loud(&self) -> String {
        self.speak().to_uppercase()
    }
}
struct Cat;
impl Speak for Cat {
    fn speak(&self) -> String { "meow".into() }
}
fn main() {
    println!("{}", Cat.loud());
}

trait Provider {
    const NAME: &'static str;
    fn label(&self) -> String {
        format!("[{}]", Self::NAME)
    }
}
struct OpenAI;
impl Provider for OpenAI {
    const NAME: &'static str = "openai";
}
fn main() {
    println!("{}", OpenAI.label());
}

struct Agent(&'static str);
fn main() {
    let s = format!("{}", Agent("goose"));
    println!("{}", s);
}

struct Paths {
    npm: bool,
    home: bool,
}
struct PathBuilder {
    npm: bool,
    home: bool,
}
impl Paths {
    fn builder() -> PathBuilder {
        PathBuilder { npm: false, home: false }
    }
}
impl PathBuilder {
    fn with_npm(mut self) -> Self { self.npm = true; self }
    fn with_home(mut self) -> Self { self.home = true; self }
    fn build(self) -> Paths { Paths { npm: self.npm, home: self.home } }
}
fn main() {
    let p = Paths::builder().with_home().build();
    println!("{} {}", p.npm, p.home);
}

fn sanitize(v: &str) -> String {
    if v.starts_with("sk-") {
        "***".into()
    } else {
        v.to_string()
    }
}
fn main() {
    let keys = vec!["sk-abc", "plain"];
    let out: Vec<String> = keys.iter().map(|k| sanitize(k)).collect();
    println!("{:?}", out);
}
